update public.sarpras_katalog set spesifikasi='{"nama_form": "Keranjang Tarik", "default": null, "variants": {"Tipe A": "Jenis Produk: Keranjang belanja tarik (shopping basket trolley) dengan roda\nMaterial: Plastik polypropylene (PP) atau HDPE berkualitas tinggi atau material sejenis yang kuat, ringan, tahan benturan, dan tahan penggunaan berulang\nKapasitas: ± 30 - 45 liter\nWarna: Merah\nDimensi: Panjang ± 430 - 650 mm, Lebar ± 300 - 420 mm, Tinggi ± 350 - 500 mm (termasuk handle dalam posisi terpasang)\nPanjang Handle Tarik: Menyesuaikan dengan desain produk\nPegangan: Dilengkapi handle tarik ergonomis dengan mekanisme tarik dan penyimpanan yang mudah digunakan\nDaya Tahan Beban: ± 15 – 30 kg\nDesain: Berlubang (ventilasi)\nDesain Samping: Terdapat area untuk penempatan logo KDKMP\nRoda: Minimal 4 (empat) roda, berbahan plastik/PU/karet atau material sejenis yang kuat dan stabil", "Tipe B": "Jenis Produk: Keranjang belanja tarik (shopping basket trolley) dengan roda\nMaterial: Plastik polypropylene (PP) atau HDPE berkualitas tinggi atau material sejenis yang kuat, ringan, tahan benturan, dan tahan penggunaan berulang\nKapasitas: ± 30 - 45 liter\nWarna: Merah\nDimensi: Panjang ± 430 - 650 mm, Lebar ± 300 - 420 mm, Tinggi ± 350 - 500 mm (termasuk handle dalam posisi terpasang)\nPanjang Handle Tarik: Menyesuaikan dengan desain produk\nPegangan: Dilengkapi handle tarik ergonomis dengan mekanisme tarik dan penyimpanan yang mudah digunakan\nDaya Tahan Beban: ± 15 – 30 kg\nDesain: Berlubang (ventilasi)\nDesain Samping: Terdapat area untuk penempatan logo KDKMP\nRoda: Minimal 4 (empat) roda, berbahan plastik/PU/karet atau material sejenis yang kuat dan stabil"}}'::jsonb,gambar='{"files": ["./assets/img/sarpras/gry_keranjang_tarik_tipe_a.jpg", "./assets/img/sarpras/gry_keranjang_tarik_tipe_b.jpg"]}'::jsonb,daftar_tipe='["Tipe A", "Tipe B"]'::jsonb where item_id='GRY_KERANJANG_TARIK';
